style.css:
@-moz-document domain("images.example.com"), url-prefix("http://www.deansys.com/doc/ldd3") {
/* ===== 阅读容器优化（核心） ===== */
  body {
    margin: 0;
    background: #f5f7fa;

    /* 字体系统 */
    font-family:
      "PingFang SC",
      "Inter",
      -apple-system,
      BlinkMacSystemFont,
      "Segoe UI",
      "Hiragino Sans GB",
      "Microsoft YaHei",
      sans-serif;

    line-height: 1.75;
    color: #1f2937;
  }

  /* 限制阅读宽度 + 居中 */
  body>* {
    max-width: 820px;
    /* 比 900 更舒服 */
    margin: 0 auto;
    padding: 24px 32px;
    background: #ffffff;
  }

  /* ===== 提升长文本可读性 ===== */
  p {
    font-size: 16px;
    letter-spacing: 0.2px;
  }

  /* ===== 标题优化 ===== */
  h1 {
    font-size: 2.2em;
    line-height: 1.3;
  }

  h2 {
    font-size: 1.6em;
  }

  h3 {
    font-size: 1.3em;
  }

  /* ===== 代码字体（重点） ===== */
  pre,
  code {
    font-family:
      "JetBrains Mono",
      "Fira Code",
      "Consolas",
      "Courier New",
      monospace;
  }

  /* ===== 代码块细节 ===== */
  pre {
    font-size: 14px;
    line-height: 1.6;
  }

  /* Firefox 兼容 */
  ::-moz-selection {
    background: #c7d2fe;
    color: #1e293b;
  }

  /* ===== 夜间模式同步优化 ===== */
  @media (prefers-color-scheme: dark) {

    body {
      background: #0f172a;
      color: #e5e7eb;
    }

    body>* {
      background: #020617;
    }

    p {
      color: #d1d5db;
    }

    ::selection {
      background: #1d4ed8;
      /* 深蓝 */
      color: #e5e7eb;
      /* 浅色文字 */
    }

    ::-moz-selection {
      background: #1d4ed8;
      color: #e5e7eb;
    }
  }
}
